+	}
+	if _, _, ok := cache.Get("b.example"); !ok {
+		t.Fatal("second entry missing")
+	}
+}
+
+func TestClusterCores_SetCopiesSlice(t *testing.T) {
+	t.Parallel()
+	cache := make(ClusterCoresCache)
+	urls := []string{"https://core.example"}
+	cache.Set("c.example", urls)
